patch:
diff --git a/repro/no-loss-of-precision-trailing-zeros.js b/repro/no-loss-of-precision-trailing-zeros.js
new file mode 100644
index 0000000..90d5f03
--- /dev/null
+++ b/repro/no-loss-of-precision-trailing-zeros.js
@@ -0,0 +1,37 @@
+"use strict";
+
+// Check for: no-loss-of-precision flags 9.000e+3 (and 9.000e3, 9.0000e4).
+// Expected: none of these literals are reported, since each is exactly
+// representable (9000 / 90000). Exits non-zero while the bug is present.
+const assert = require("node:assert");
+const path = require("node:path");
+const { Linter } = require(path.join(__dirname, "..", "lib", "api.js"));
+
+const linter = new Linter();
+const config = [{ rules: { "no-loss-of-precision": "error" } }];
+
+// Literals taken from the report and the maintainer's follow-up comment.
+const literals = ["9.000e+3", "9.000e3", "9.0000e4"];
+
+let failed = false;
+
+for (const literal of literals) {
+	const messages = linter.verify(`const test = ${literal};`, config);
+
+	try {
+		assert.deepStrictEqual(
+			messages.map(m => `${m.ruleId}: ${m.message}`),
+			[],
+			`${literal} should not be reported`,
+		);
+		console.log(`ok   ${literal}`);
+	} catch (error) {
+		failed = true;
+		console.log(`FAIL ${literal}: ${error.message.split("\n")[0]}`);
+		for (const m of messages) {
+			console.log(`       reported: ${m.ruleId}: ${m.message}`);
+		}
+	}
+}
+
+process.exitCode = failed ? 1 : 0;
